  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches, coarse = matchMedia('(pointer: coarse)').matches, root = document.documentElement;
  const safe = f => { try { return f(); } catch { return null; } }, sleep = ms => new Promise(r => setTimeout(r, ms)), clamp = (x, a, b) => Math.min(b, Math.max(a, x));
  const cfg = JSON.parse($('#cfg').textContent), langs = cfg.languages || ['en'];

  /* language */
  const lb = $('#lang');
  const setLang = l => { root.lang = l; root.dir = l === 'fa' ? 'rtl' : 'ltr'; if (lb) lb.textContent = l === 'fa' ? 'English' : 'فارسی'; if (cfg.titles && cfg.titles[l]) document.title = cfg.titles[l]; safe(() => localStorage.setItem('site-lang', l)); document.dispatchEvent(new Event('langchange')); };
  if (langs.length > 1 && lb) { lb.addEventListener('click', () => setLang(root.lang === 'fa' ? 'en' : 'fa')); setLang(safe(() => localStorage.getItem('site-lang')) || ((navigator.language || '').startsWith('fa') ? 'fa' : langs[0])); } else { setLang(langs[0]); }
  const isFa = () => root.lang === 'fa';

  /* headline: words, never letters */
  const splitWords = (el, grad) => { for (const n of [...el.childNodes]) { if (n.nodeType === 3) { const f = document.createDocumentFragment(); n.textContent.split(/(\s+)/).forEach(t => { if (!t) return; if (/^\s+$/.test(t)) { f.appendChild(document.createTextNode(' ')); return; } const w = document.createElement('span'); w.className = 'w' + (grad ? ' grad' : ''); w.textContent = t; f.appendChild(w); }); n.replaceWith(f); } else if (n.nodeType === 1) splitWords(n, grad || n.classList.contains('grad')); } };
  const h1 = $('#h1'); if (h1) { $$('[lang]', h1).filter(e => e.parentElement === h1).forEach(e => splitWords(e)); $$('.grad', h1).forEach(g => { if (!g.classList.contains('w')) g.classList.remove('grad'); }); let i = 0; $$('.w', h1).forEach(w => w.style.setProperty('--i', i++ % 14)); }
