  addEventListener('scroll', () => { if (tick) return; tick = true; requestAnimationFrame(() => { tick = false; const y = scrollY, max = root.scrollHeight - innerHeight; root.style.setProperty('--sp', max > 0 ? (y / max).toFixed(4) : 0); nav.classList.toggle('hide', y > 500 && y > lastY + 4); if (y < lastY - 4 || y < 500) nav.classList.remove('hide'); lastY = y; }); }, { passive: true });
