  const cio = new IntersectionObserver(es => es.forEach(e => { if (!e.isIntersecting) return; cio.unobserve(e.target); const el = e.target, to = +el.dataset.count, suf = el.dataset.suffix || '', t0 = performance.now(); if (reduce) { el.textContent = to + suf; return; } (function f(now) { const p = clamp((now - t0) / 1500, 0, 1); el.textContent = Math.round(to * (1 - Math.pow(2, -10 * p))) + suf; if (p < 1) requestAnimationFrame(f); else el.textContent = to + suf; })(t0); }), { threshold: .6 }); $$('[data-count]').forEach(el => cio.observe(el));

  /* pointer effects */
  if (!coarse && !reduce) {
    const g = $('#glow'); let gx = innerWidth / 2, gy = innerHeight / 3, tx = gx, ty = gy; addEventListener('pointermove', e => { tx = e.clientX; ty = e.clientY; }, { passive: true }); (function f() { gx += (tx - gx) * .12; gy += (ty - gy) * .12; g.style.transform = `translate3d(${gx}px,${gy}px,0)`; requestAnimationFrame(f); })();
    $$('.mag').forEach(b => { b.addEventListener('pointermove', e => { const r = b.getBoundingClientRect(); b.style.transform = `translate(${(e.clientX - r.left - r.width / 2) * .22}px,${(e.clientY - r.top - r.height / 2) * .3}px)`; }); b.addEventListener('pointerleave', () => { b.style.transform = ''; }); });
    document.addEventListener('pointermove', e => { const t = e.target.closest && e.target.closest('.fcard,.pn,.qa'); if (!t) return; const r = t.getBoundingClientRect(); t.style.setProperty('--sx', (e.clientX - r.left) + 'px'); t.style.setProperty('--sy', (e.clientY - r.top) + 'px'); }, { passive: true });
  }

