  const slot = $('#rot'); if (slot && cfg.words) { let i = 0, cur = null; const show = () => { const list = cfg.words[isFa() ? 'fa' : 'en'] || cfg.words.en, s = document.createElement('span'); s.textContent = list[i % list.length]; s.className = 'pre'; slot.appendChild(s); slot.style.width = s.offsetWidth + 4 + 'px'; void s.offsetWidth; s.className = ''; if (cur) { const o = cur; o.className = 'out'; setTimeout(() => o.remove(), 700); } cur = s; i++; }; show(); if (!reduce) setInterval(show, 2300); document.addEventListener('langchange', () => { slot.innerHTML = ''; cur = null; i = 0; show(); }); }

  /* install tabs, copy, typing terminal */
  const tabs = $('#itabs'); if (tabs) tabs.addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; $$('#itabs button').forEach(x => x.setAttribute('aria-selected', x === b)); $$('.panel').forEach(p => p.classList.toggle('on', p.id === b.dataset.p)); });
  document.addEventListener('click', async e => { const b = e.target.closest('.cp'); if (!b) return; const src = b.dataset.copy ? $(b.dataset.copy) : b.parentElement.querySelector('pre'); if (!src) return; const old = b.innerHTML; try { await navigator.clipboard.writeText(src.innerText.replace(/^\$ /, '')); b.textContent = isFa() ? 'کپی شد ✓' : 'copied ✓'; } catch { b.textContent = 'Ctrl+C'; } setTimeout(() => { b.innerHTML = old; }, 1500); });
  const cmd = $('#hero-cmd'); if (cmd && cfg.heroCommand) { if (reduce) cmd.textContent = cfg.heroCommand; else (async () => { await sleep(900); for (const ch of cfg.heroCommand) { cmd.textContent += ch; await sleep(16 + Math.random() * 14); } const c = $('.caret'); if (c) c.remove(); })(); }
